// ================= SAFE INIT =================

document.addEventListener('DOMContentLoaded', () => {

    /*
     * Find the navigation map.
     *
     * If this page does not contain the navigation map,
     * stop execution safely.
     */
    const mapEl = document.getElementById('navMap');

    if (!mapEl) {
        return;
    }


    // ================= DESTINATION DATA =================

    /*
     * Read the destination coordinates generated by Laravel.
     *
     * Number() converts the data attributes from strings
     * into JavaScript numbers.
     */
    const lat = Number(mapEl.dataset.lat);
    const lng = Number(mapEl.dataset.lng);
    const name = mapEl.dataset.name || 'Destination';


    /*
     * Coordinates are mandatory for routing.
     *
     * Reject invalid values before initializing any
     * location or routing functionality.
     */
    if (
        !Number.isFinite(lat) ||
        !Number.isFinite(lng)
    ) {

        console.error('Invalid agency coordinates.');

        return;
    }


    // ================= ICONS =================

    /*
     * User location marker.
     */
    const userIcon = L.divIcon({

        className: '',

        html:
            '<div class="user-marker"></div>',

        iconSize: [14, 14],

        iconAnchor: [7, 7]

    });


    /*
     * Agency destination marker.
     */
    const destIcon = L.divIcon({

        className: '',

        html:
            '<div class="dest-marker">' +
                '<i class="ph-light ph-buildings"></i>' +
            '</div>',

        iconSize: [30, 30],

        iconAnchor: [15, 15]

    });


    // ================= MAP =================

    /*
     * Initialize the Leaflet map.
     *
     * zoomControl is disabled because we create our
     * own modern controls later.
     */
    const navMap =
        L.map('navMap', {

            zoomControl: false

        }).setView(
            [lat, lng],
            16
        );


    /*
     * OpenStreetMap base layer.
     */
    L.tileLayer(
        'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
        {

            maxZoom: 19,

            attribution:
                '&copy; OpenStreetMap contributors'

        }
    ).addTo(navMap);


    // ================= DESTINATION =================

    /*
     * Display the agency marker.
     *
     * This marker remains fixed because the agency
     * destination does not change.
     */
    const destinationMarker =
        L.marker(
            [lat, lng],
            {
                icon: destIcon
            }
        ).addTo(navMap);


    /*
     * Permanent agency name label.
     */
    const destinationTooltip =
        L.tooltip({

            permanent: true,

            direction: 'top',

            offset: [0, -18],

            className: 'dest-tooltip'

        })
        .setContent(name)
        .setLatLng([lat, lng])
        .addTo(navMap);


    // ================= ROUTING STATE =================

    /*
     * Current Leaflet Routing Machine control.
     */
    let routingControl = null;


    /*
     * Car is the default travel mode.
     */
    let selectedTravelMode = 'driving';


    /*
     * User's marker.
     */
    let userMarker = null;


    /*
     * Latest GPS position.
     */
    let userLocation = null;


    /*
     * Determines whether the initial GPS update
     * has already been processed.
     */
    let isFirstUpdate = true;


    /*
     * Current route coordinates.
     *
     * Used by destination-label collision detection
     * and the Fit Route control.
     */
    let currentRouteCoordinates = [];


    /*
     * Latest detailed route.
     *
     * Stored so the map can quickly fit the route
     * without requesting another route.
     */
    let currentRoute = null;


    /*
     * Prevent an older route request from replacing
     * a newer route request.
     */
    let routeRequestId = 0;


    // ================= ETA STATE =================

    /*
     * Last GPS position used for ETA calculation.
     */
    let lastEtaLocation = null;


    /*
     * Prevent overlapping ETA request batches.
     */
    let etaRequestInProgress = false;


    /*
     * User must move at least 100 meters before
     * another ETA batch is requested.
     */
    const ETA_MIN_DISTANCE = 100;


    // ================= TRAVEL SPEEDS =================

    /*
     * Representative average travel speeds.
     *
     * These values are used by KNOWURLOCAL's own
     * travel-time estimation formula:
     *
     *     Time = Distance / Speed
     *
     * These are representative assumptions.
     * They are NOT real-time traffic speeds.
     */
    const TRAVEL_SPEEDS = {

        walking: 4.7,

        motorcycle: 27,

        driving: 25

    };


    // ================= ROUTING CONFIGURATION =================

    /*
     * Routing configuration for each transportation mode.
     *
     * Motorcycle uses the bicycle routing profile as
     * a route approximation.
     *
     * The motorcycle ETA still uses the motorcycle
     * representative speed of 27 km/h.
     */
    const routeModeConfig = {

        walking: {

            serviceUrl:
                'https://routing.openstreetmap.de/routed-foot/route/v1',

            profile:
                'foot',

            name:
                'Walking',

            icon:
                'ph-person-simple-walk'

        },


        motorcycle: {

            serviceUrl:
                'https://router.project-osrm.org/route/v1',

            profile:
                'bike',

            name:
                'Motorcycle',

            icon:
                'ph-motorcycle'

        },


        driving: {

            serviceUrl:
                'https://routing.openstreetmap.de/routed-car/route/v1',

            profile:
                'driving',

            name:
                'Car',

            icon:
                'ph-car'

        }

    };


    // ================= TRAVEL MODE ELEMENTS =================

    /*
     * Find all transportation mode cards.
     */
    const travelModeElements =
        document.querySelectorAll(
            '.travel-mode'
        );


    // ================= GPS STATUS =================

    /*
     * Elements used to communicate GPS state.
     */
    const locationStatus =
        document.getElementById(
            'locationStatus'
        );

    const locationStatusIcon =
        document.getElementById(
            'locationStatusIcon'
        );

    const locationStatusText =
        document.getElementById(
            'locationStatusText'
        );


    /*
     * Update the small floating GPS status indicator.
     *
     * This gives the user feedback instead of relying
     * on browser alerts.
     */
    function updateLocationStatus(
        state,
        message
    ) {

        if (
            !locationStatus ||
            !locationStatusIcon ||
            !locationStatusText
        ) {

            return;

        }


        locationStatus.className =
            `location-status ${state}`;


        locationStatusText.textContent =
            message;


        const icons = {

            loading:
                'ph-spinner',

            success:
                'ph-check-circle',

            error:
                'ph-warning-circle'

        };


        const icon =
            icons[state] || 'ph-info';


        locationStatusIcon.className =
            `ph-light ${icon}`;


        /*
         * Loading state gets a subtle spinning animation.
         */
        locationStatusIcon.classList.toggle(
            'is-spinning',
            state === 'loading'
        );

    }


    // ================= ROUTE HINT =================

    const routeHint =
        document.getElementById(
            'routeHint'
        );

    const routeHintIcon =
        document.getElementById(
            'routeHintIcon'
        );

    const routeHintTitle =
        document.getElementById(
            'routeHintTitle'
        );

    const routeHintSubtitle =
        document.getElementById(
            'routeHintSubtitle'
        );


    let routeHintTimeout = null;


    // ================= MAP CONTROLS =================

    /*
     * Custom map-control container.
     *
     * The buttons are intentionally created through
     * JavaScript so they remain tightly coupled to
     * the navigation behavior.
     */
    const mapControls =
        L.control({
            position: 'topright'
        });


    mapControls.onAdd =
        function () {

            const container =
                L.DomUtil.create(
                    'div',
                    'nav-map-controls'
                );


            /*
             * Stop map interactions from being triggered
             * when the user interacts with our buttons.
             */
            L.DomEvent.disableClickPropagation(
                container
            );


            L.DomEvent.disableScrollPropagation(
                container
            );


            // ================= MY LOCATION =================

            const locationButton =
                L.DomUtil.create(
                    'button',
                    'nav-map-control',
                    container
                );


            locationButton.type =
                'button';


            locationButton.setAttribute(
                'aria-label',
                'Center map on my location'
            );


            locationButton.setAttribute(
                'title',
                'My location'
            );


            locationButton.innerHTML =
                '<i class="ph-light ph-crosshair"></i>';


            locationButton.addEventListener(
                'click',
                () => {

                    if (!userLocation) {

                        updateLocationStatus(
                            'loading',
                            'Getting your location…'
                        );

                        return;

                    }


                    navMap.flyTo(
                        [
                            userLocation.lat,
                            userLocation.lng
                        ],
                        Math.max(
                            navMap.getZoom(),
                            16
                        ),
                        {

                            animate:
                                true,

                            duration:
                                0.8

                        }

                    );

                }
            );


            // ================= FIT ROUTE =================

            const fitButton =
                L.DomUtil.create(
                    'button',
                    'nav-map-control',
                    container
                );


            fitButton.type =
                'button';


            fitButton.setAttribute(
                'aria-label',
                'Fit route on map'
            );


            fitButton.setAttribute(
                'title',
                'Fit route'
            );


            fitButton.innerHTML =
                '<i class="ph-light ph-arrows-out"></i>';


            fitButton.addEventListener(
                'click',
                () => {

                    fitRouteToMap();

                }
            );


            return container;

        };


    mapControls.addTo(navMap);


    // ================= DIRECTIONS MODAL =================

    const modal =
        document.getElementById(
            'routeModal'
        );

    const openBtn =
        document.getElementById(
            'openRoute'
        );

    const closeBtn =
        document.getElementById(
            'closeRoute'
        );


    // ================= DESTINATION LABEL COLLISION =================

    function rectanglesOverlap(a, b) {

        return !(
            a.right < b.left ||
            a.left > b.right ||
            a.bottom < b.top ||
            a.top > b.bottom
        );

    }


    function getSegmentBounds(
        pointA,
        pointB,
        padding = 5
    ) {

        return {

            left:
                Math.min(
                    pointA.x,
                    pointB.x
                ) - padding,

            right:
                Math.max(
                    pointA.x,
                    pointB.x
                ) + padding,

            top:
                Math.min(
                    pointA.y,
                    pointB.y
                ) - padding,

            bottom:
                Math.max(
                    pointA.y,
                    pointB.y
                ) + padding

        };

    }


    function tooltipBlocksRoute(
        tooltipElement
    ) {

        if (
            !tooltipElement ||
            currentRouteCoordinates.length < 2
        ) {

            return false;

        }


        const tooltipRect =
            tooltipElement.getBoundingClientRect();


        const mapRect =
            navMap
                .getContainer()
                .getBoundingClientRect();


        const tooltipMapRect = {

            left:
                tooltipRect.left -
                mapRect.left,

            right:
                tooltipRect.right -
                mapRect.left,

            top:
                tooltipRect.top -
                mapRect.top,

            bottom:
                tooltipRect.bottom -
                mapRect.top

        };


        const routePoints =
            currentRouteCoordinates.map(
                coordinate =>
                    navMap.latLngToContainerPoint(
                        coordinate
                    )
            );


        for (
            let i = 0;
            i < routePoints.length - 1;
            i++
        ) {

            const segmentBounds =
                getSegmentBounds(
                    routePoints[i],
                    routePoints[i + 1]
                );


            if (
                rectanglesOverlap(
                    tooltipMapRect,
                    segmentBounds
                )
            ) {

                return true;

            }

        }


        return false;

    }


    function repositionDestinationLabel() {

        if (!destinationTooltip) {
            return;
        }


        const tooltipElement =
            destinationTooltip.getElement();


        if (!tooltipElement) {
            return;
        }


        const positions = [

            {
                direction: 'top',
                offset: [0, -22]
            },

            {
                direction: 'right',
                offset: [22, 0]
            },

            {
                direction: 'bottom',
                offset: [0, 22]
            },

            {
                direction: 'left',
                offset: [-22, 0]
            }

        ];


        for (
            const position of positions
        ) {

            destinationTooltip.options.direction =
                position.direction;


            destinationTooltip.options.offset =
                position.offset;


            destinationTooltip.update();


            if (
                !tooltipBlocksRoute(
                    tooltipElement
                )
            ) {

                return;

            }

        }


        destinationTooltip.options.direction =
            'top';


        destinationTooltip.options.offset =
            [0, -22];


        destinationTooltip.update();

    }


    // ================= ROUTE FITTING =================

    function fitRouteToMap() {

        /*
         * If a detailed route exists, use its bounds.
         */
        if (
            currentRoute &&
            currentRoute.bounds
        ) {

            navMap.fitBounds(
                currentRoute.bounds,
                {

                    paddingTopLeft:
                        [30, 100],

                    paddingBottomRight:
                        [30, 230],

                    maxZoom:
                        17,

                    animate:
                        true,

                    duration:
                        0.8

                }
            );


            return;

        }


        /*
         * If no route exists yet but the user's
         * location is available, fit both points.
         */
        if (userLocation) {

            const bounds =
                L.latLngBounds([

                    [
                        userLocation.lat,
                        userLocation.lng
                    ],

                    [
                        lat,
                        lng
                    ]

                ]);


            navMap.fitBounds(
                bounds,
                {

                    paddingTopLeft:
                        [30, 100],

                    paddingBottomRight:
                        [30, 230],

                    maxZoom:
                        17,

                    animate:
                        true,

                    duration:
                        0.8

                }
            );

        }

    }


    // ================= ETA CALCULATION =================

    /*
     * Calculate straight-line distance between
     * two GPS positions.
     *
     * This is ONLY used to determine whether the
     * user has moved enough to recalculate ETA.
     *
     * It is NOT used as the travel route distance.
     */
    function calculateDistance(
        lat1,
        lng1,
        lat2,
        lng2
    ) {

        const earthRadius =
            6371000;


        const latDifference =
            (lat2 - lat1) *
            Math.PI /
            180;


        const lngDifference =
            (lng2 - lng1) *
            Math.PI /
            180;


        const a =
            Math.sin(
                latDifference / 2
            ) ** 2 +

            Math.cos(
                lat1 * Math.PI / 180
            ) *

            Math.cos(
                lat2 * Math.PI / 180
            ) *

            Math.sin(
                lngDifference / 2
            ) ** 2;


        const c =
            2 *
            Math.atan2(
                Math.sqrt(a),
                Math.sqrt(1 - a)
            );


        return earthRadius * c;

    }


    /*
     * Calculate estimated travel time.
     *
     * Formula:
     *
     *     Time = Distance / Speed
     */
    function calculateTravelTime(
        distanceMeters,
        mode
    ) {

        const speedKmh =
            TRAVEL_SPEEDS[mode];


        if (
            !Number.isFinite(distanceMeters) ||
            distanceMeters < 0 ||
            !Number.isFinite(speedKmh) ||
            speedKmh <= 0
        ) {

            return null;

        }


        const distanceKm =
            distanceMeters / 1000;


        const timeHours =
            distanceKm / speedKmh;


        return timeHours * 60;

    }


    /*
     * Convert calculated minutes into
     * human-readable text.
     */
    function formatTravelTime(minutes) {

        if (
            !Number.isFinite(minutes) ||
            minutes < 0
        ) {

            return 'Unavailable';

        }


        const roundedMinutes =
            Math.round(minutes);


        if (
            roundedMinutes < 1
        ) {

            return '<1 min';

        }


        if (
            roundedMinutes < 60
        ) {

            return `${roundedMinutes} min`;

        }


        const hours =
            Math.floor(
                roundedMinutes / 60
            );


        const remainingMinutes =
            roundedMinutes % 60;


        if (
            remainingMinutes === 0
        ) {

            return `${hours} hr`;

        }


        return `${hours} hr ${remainingMinutes} min`;

    }


    /*
     * Format a route distance.
     */
    function formatDistance(
        distanceMeters
    ) {

        if (
            !Number.isFinite(distanceMeters) ||
            distanceMeters < 0
        ) {

            return '';

        }


        if (
            distanceMeters >= 1000
        ) {

            return `${
                (distanceMeters / 1000).toFixed(1)
            } km`;

        }


        return `${Math.round(distanceMeters)} m`;

    }


    // ================= TRAVEL CARD UI =================

    function updateTravelCard(
        mode,
        formattedTime,
        distanceMeters = null
    ) {

        const modeElement =
            document.querySelector(
                `.travel-mode[data-mode="${mode}"]`
            );


        if (!modeElement) {
            return;
        }


        const timeElement =
            modeElement.querySelector(
                '.travel-mode-time'
            );


        const distanceElement =
            modeElement.querySelector(
                '.travel-mode-distance'
            );


        if (!timeElement) {
            return;
        }


        timeElement.textContent =
            formattedTime;


        timeElement.classList.remove(
            'loading',
            'error'
        );


        if (
            formattedTime === 'Unavailable'
        ) {

            timeElement.classList.add(
                'error'
            );

        }


        if (distanceElement) {

            distanceElement.textContent =
                formatDistance(
                    distanceMeters
                );

        }


        if (
            mode === selectedTravelMode &&
            formattedTime !== 'Unavailable'
        ) {

            showRouteHint(mode);

        }

    }


    function setTravelCardsLoading() {

        travelModeElements.forEach(
            element => {

                const timeElement =
                    element.querySelector(
                        '.travel-mode-time'
                    );


                const distanceElement =
                    element.querySelector(
                        '.travel-mode-distance'
                    );


                if (timeElement) {

                    timeElement.textContent =
                        'Calculating...';


                    timeElement.classList.remove(
                        'error'
                    );


                    timeElement.classList.add(
                        'loading'
                    );

                }


                if (distanceElement) {

                    distanceElement.textContent =
                        '';

                }

            }
        );

    }


    // ================= ROUTE HINT =================

    function showRouteHint(mode) {

        const config =
            routeModeConfig[mode];


        if (
            !config ||
            !routeHint ||
            !routeHintIcon ||
            !routeHintTitle ||
            !routeHintSubtitle
        ) {

            return;

        }


        routeHintIcon.className =
            `ph-light ${config.icon}`;


        const selectedModeElement =
            document.querySelector(
                `.travel-mode[data-mode="${mode}"]`
            );


        const selectedTimeElement =
            selectedModeElement?.querySelector(
                '.travel-mode-time'
            );


        const selectedDistanceElement =
            selectedModeElement?.querySelector(
                '.travel-mode-distance'
            );


        const selectedTime =
            selectedTimeElement?.textContent || '';


        const selectedDistance =
            selectedDistanceElement?.textContent || '';


        routeHintTitle.textContent =
            selectedTime &&
            selectedTime !== 'Calculating...' &&
            selectedTime !== 'Unavailable'

                ? `${config.name} · ${selectedTime}`

                : `${config.name} route`;


        routeHintSubtitle.textContent =
            selectedDistance
                ? `${selectedDistance} · Tap for directions`
                : 'Tap to view directions';


        clearTimeout(
            routeHintTimeout
        );


        routeHint.setAttribute(
            'tabindex',
            '0'
        );


        routeHint.classList.add(
            'active'
        );


        routeHintTimeout =
            setTimeout(
                () => {

                    hideRouteHint();

                },
                4000
            );

    }


    function hideRouteHint() {

        clearTimeout(
            routeHintTimeout
        );


        if (
            document.activeElement === routeHint
        ) {

            routeHint.blur();

        }


        routeHint.classList.remove(
            'active'
        );


        routeHint.setAttribute(
            'tabindex',
            '-1'
        );

    }


    // ================= DIRECTIONS HEADER =================

    function updateDirectionsHeader(
        mode,
        summary = 'Calculating route...'
    ) {

        const config =
            routeModeConfig[mode];


        if (!config) {
            return;
        }


        const iconContainer =
            document.getElementById(
                'routeModeIcon'
            );

        const nameElement =
            document.getElementById(
                'routeModeName'
            );

        const summaryElement =
            document.getElementById(
                'routeModeSummary'
            );


        if (
            !iconContainer ||
            !nameElement ||
            !summaryElement
        ) {

            return;

        }


        iconContainer.innerHTML =
            `<i class="ph-light ${config.icon}"></i>`;


        nameElement.textContent =
            `${config.name} directions`;


        summaryElement.textContent =
            summary;


        iconContainer.classList.remove(
            'route-mode-change'
        );


        void iconContainer.offsetWidth;


        iconContainer.classList.add(
            'route-mode-change'
        );

    }


    // ================= DIRECTION CLICK HANDLERS =================

    function attachDirectionClickHandlers() {

        const directionRows =
            document.querySelectorAll(
                '#routeContainer .leaflet-routing-alt tr'
            );


        directionRows.forEach(
            row => {

                if (
                    row.dataset.modalCloseAttached === 'true'
                ) {

                    return;

                }


                row.dataset.modalCloseAttached =
                    'true';


                row.addEventListener(
                    'click',
                    () => {

                        setTimeout(
                            () => {

                                if (modal) {

                                    modal.classList.remove(
                                        'active'
                                    );

                                }

                            },
                            0
                        );

                    }
                );

            }
        );

    }


    // ================= DETAILED ROUTE =================

    function createRoute(
        userLat,
        userLng,
        mode = selectedTravelMode
    ) {

        const config =
            routeModeConfig[mode];


        if (!config) {

            console.error(
                'Unsupported travel mode:',
                mode
            );

            return;

        }


        /*
         * Increment the request identifier.
         *
         * If a newer route request starts later,
         * an older asynchronous result can be ignored.
         */
        const requestId =
            ++routeRequestId;


        /*
         * Remove the previous routing control.
         */
        if (routingControl) {

            navMap.removeControl(
                routingControl
            );

            routingControl = null;

        }


        /*
         * Clear the previous route state.
         */
        currentRoute =
            null;


        currentRouteCoordinates =
            [];


        /*
         * Clear old directions.
         */
        const routeContainer =
            document.getElementById(
                'routeContainer'
            );


        if (routeContainer) {

            routeContainer.innerHTML = '';

        }


        /*
         * Update the modal immediately so the user
         * sees which mode is being calculated.
         */
        updateDirectionsHeader(
            mode,
            'Calculating route...'
        );


        /*
         * All current routing modes use OSRM.
         */
        const router =
            L.Routing.osrmv1({

                serviceUrl:
                    config.serviceUrl,

                profile:
                    config.profile

            });


        /*
         * Create the Leaflet Routing Machine control.
         */
        routingControl =
            L.Routing.control({

                waypoints: [

                    L.latLng(
                        userLat,
                        userLng
                    ),

                    L.latLng(
                        lat,
                        lng
                    )

                ],

                addWaypoints:
                    false,

                draggableWaypoints:
                    false,

                showAlternatives:
                    false,

                router,

                lineOptions: {

                    styles: [{

                        color:
                            '#7c3aed',

                        weight:
                            6,

                        opacity:
                            0.9

                    }]

                },

                createMarker:
                    () => null

            }).addTo(navMap);


        /*
         * Move the generated LRM panel into
         * our custom directions modal.
         */
        const panel =
            routingControl.getContainer();


        const container =
            document.getElementById(
                'routeContainer'
            );


        if (
            panel &&
            container &&
            !container.contains(panel)
        ) {

            container.appendChild(panel);

        }


        // ================= ROUTE RESULT =================

        routingControl.on(
            'routesfound',
            event => {

                /*
                 * Ignore results from an outdated
                 * route request.
                 */
                if (
                    requestId !== routeRequestId
                ) {

                    return;

                }


                const route =
                    event.routes?.[0];


                if (!route) {

                    handleDetailedRouteError(
                        mode
                    );

                    return;

                }


                currentRoute =
                    route;


                currentRouteCoordinates =
                    route.coordinates || [];


                requestAnimationFrame(
                    () => {

                        repositionDestinationLabel();

                    }
                );


                queueMicrotask(
                    () => {

                        if (
                            routingControl &&
                            requestId === routeRequestId
                        ) {

                            routingControl.setAlternatives([
                                route
                            ]);

                        }

                    }
                );


                requestAnimationFrame(
                    () => {

                        attachDirectionClickHandlers();

                    }
                );


                /*
                 * Use the actual road-route distance.
                 */
                const distance =
                    route.summary?.totalDistance;


                /*
                 * Calculate ETA using our representative
                 * transportation-mode speed.
                 */
                const calculatedMinutes =
                    calculateTravelTime(
                        distance,
                        mode
                    );


                const timeText =
                    formatTravelTime(
                        calculatedMinutes
                    );


                const distanceText =
                    formatDistance(
                        distance
                    );


                const summary =
                    timeText !== 'Unavailable' &&
                    distanceText

                        ? `${timeText} · ${distanceText}`

                        : timeText;


                updateDirectionsHeader(
                    mode,
                    summary
                );


                /*
                 * A detailed route was successfully
                 * calculated, so update the map controls
                 * and the destination label.
                 */
                requestAnimationFrame(
                    () => {

                        repositionDestinationLabel();

                    }
                );

            }
        );


        // ================= ROUTE ERROR =================

        routingControl.on(
            'routingerror',
            () => {

                if (
                    requestId !== routeRequestId
                ) {

                    return;

                }


                handleDetailedRouteError(
                    mode
                );

            }
        );

    }


    function handleDetailedRouteError(
        mode
    ) {

        currentRoute =
            null;


        currentRouteCoordinates =
            [];


        updateDirectionsHeader(
            mode,
            'Route unavailable'
        );


        /*
         * Show a clear message inside the directions
         * container instead of leaving an empty panel.
         */
        const container =
            document.getElementById(
                'routeContainer'
            );


        if (container) {

            container.innerHTML = `

                <div class="route-error-state">

                    <i
                        class="ph-light ph-map-trifold"
                        aria-hidden="true"
                    ></i>

                    <strong>
                        Route unavailable
                    </strong>

                    <span>
                        We couldn't calculate a route
                        for this travel mode right now.
                    </span>

                </div>

            `;

        }

    }


    // ================= EXISTING ROUTE UPDATE =================

    function updateRoute(
        userLat,
        userLng
    ) {

        if (!routingControl) {
            return;
        }


        routingControl.setWaypoints([

            L.latLng(
                userLat,
                userLng
            ),

            L.latLng(
                lat,
                lng
            )

        ]);

    }


    // ================= ETA ROUTING =================

    /*
     * Calculate a route for one transportation mode.
     *
     * The route distance is used by
     * KNOWURLOCAL's own ETA calculation.
     */
    async function calculateTravelMode(
        mode,
        userLat,
        userLng
    ) {

        const config =
            routeModeConfig[mode];


        if (!config) {

            console.error(
                'Unknown travel mode:',
                mode
            );

            return;

        }


        /*
         * Build the OSRM coordinate pair.
         *
         * OSRM expects:
         *
         *     longitude,latitude
         */
        const coordinates =
            `${userLng},${userLat};${lng},${lat}`;


        /*
         * Request only the route information required
         * for ETA calculation.
         */
        const url =
            `${config.serviceUrl}/${config.profile}/${coordinates}` +
            '?overview=false&steps=false';


        /*
         * AbortController allows us to stop a request
         * that takes too long.
         */
        const controller =
            new AbortController();


        const timeout =
            setTimeout(
                () => controller.abort(),
                15000
            );


        try {

            const response =
                await fetch(
                    url,
                    {

                        method:
                            'GET',

                        signal:
                            controller.signal,

                        headers: {

                            Accept:
                                'application/json'

                        }

                    }
                );


            /*
             * Reject unsuccessful HTTP responses.
             */
            if (!response.ok) {

                throw new Error(
                    `Routing request failed: ${response.status}`
                );

            }


            /*
             * Parse the JSON response.
             */
            const data =
                await response.json();


            /*
             * Use the first returned route.
             */
            const route =
                data.routes?.[0];


            if (!route) {

                throw new Error(
                    'No route returned.'
                );

            }


            /*
             * Log the actual road-route distance.
             */
            console.log(
                `[KNOWURLOCAL] ${mode} route distance:`,
                route.distance,
                'meters'
            );


            /*
             * Calculate travel time using the
             * representative mode speed.
             */
            const calculatedMinutes =
                calculateTravelTime(
                    route.distance,
                    mode
                );


            const formattedTime =
                formatTravelTime(
                    calculatedMinutes
                );


            /*
             * Update both ETA and route distance.
             */
            updateTravelCard(
                mode,
                formattedTime,
                route.distance
            );

        } catch (error) {

            console.error(
                `Travel time request failed for ${mode}:`,
                error
            );


            /*
             * Find the affected travel card.
             */
            const modeElement =
                document.querySelector(
                    `.travel-mode[data-mode="${mode}"]`
                );


            const timeElement =
                modeElement?.querySelector(
                    '.travel-mode-time'
                );


            const distanceElement =
                modeElement?.querySelector(
                    '.travel-mode-distance'
                );


            /*
             * Tell the user when the route
             * could not be calculated.
             */
            if (timeElement) {

                timeElement.textContent =
                    'Unavailable';


                timeElement.classList.remove(
                    'loading'
                );


                timeElement.classList.add(
                    'error'
                );

            }


            if (distanceElement) {

                distanceElement.textContent =
                    '';

            }

        } finally {

            /*
             * Always clear the timeout after
             * the request finishes.
             */
            clearTimeout(
                timeout
            );

        }

    }


    // ================= REQUEST DELAY =================

    function wait(
        milliseconds
    ) {

        return new Promise(
            resolve =>
                setTimeout(
                    resolve,
                    milliseconds
                )

        );

    }


    // ================= ALL ETA REQUESTS =================

    async function updateTravelTimes(
        userLat,
        userLng
    ) {

        /*
         * Prevent multiple ETA batches from
         * running simultaneously.
         */
        if (
            etaRequestInProgress
        ) {

            return;

        }


        /*
         * Only recalculate when the user has moved
         * at least 100 meters.
         */
        if (
            lastEtaLocation
        ) {

            const distance =
                calculateDistance(
                    lastEtaLocation.lat,
                    lastEtaLocation.lng,
                    userLat,
                    userLng
                );


            if (
                distance < ETA_MIN_DISTANCE
            ) {

                return;

            }

        }


        /*
         * Store the GPS position used for this
         * ETA calculation batch.
         */
        lastEtaLocation = {

            lat:
                userLat,

            lng:
                userLng

        };


        etaRequestInProgress =
            true;


        setTravelCardsLoading();


        try {

            /*
             * Walking uses OSRM foot routing.
             */
            await calculateTravelMode(
                'walking',
                userLat,
                userLng
            );


            /*
             * Delay the next request to avoid
             * sending all requests simultaneously.
             */
            await wait(
                1100
            );


            /*
             * Motorcycle uses OSRM bicycle routing
             * with the motorcycle speed assumption.
             */
            await calculateTravelMode(
                'motorcycle',
                userLat,
                userLng
            );


            await wait(
                1100
            );


            /*
             * Car uses OSRM driving routing.
             */
            await calculateTravelMode(
                'driving',
                userLat,
                userLng
            );

        } finally {

            /*
             * Allow another ETA batch once this
             * batch has finished.
             */
            etaRequestInProgress =
                false;

        }

    }


    // ================= TRAVEL MODE SELECTION =================

    function updateTravelModeUI(
        mode
    ) {

        travelModeElements.forEach(
            element => {

                const isActive =
                    element.dataset.mode === mode;


                element.classList.toggle(
                    'active',
                    isActive
                );


                element.setAttribute(
                    'aria-pressed',
                    isActive
                        ? 'true'
                        : 'false'
                );

            }
        );

    }


    function selectTravelMode(
        mode
    ) {

        if (
            !routeModeConfig[mode]
        ) {

            return;

        }


        if (
            selectedTravelMode === mode
        ) {

            return;

        }


        selectedTravelMode =
            mode;


        updateTravelModeUI(
            mode
        );


        updateDirectionsHeader(
            mode
        );


        showRouteHint(
            mode
        );


        if (!userLocation) {

            return;

        }


        createRoute(
            userLocation.lat,
            userLocation.lng,
            selectedTravelMode
        );

    }


    // ================= MODE INTERACTION =================

    travelModeElements.forEach(
        element => {

            element.addEventListener(
                'click',
                () => {

                    selectTravelMode(
                        element.dataset.mode
                    );

                }
            );


            element.addEventListener(
                'keydown',
                event => {

                    if (
                        event.key === 'Enter' ||
                        event.key === ' '
                    ) {

                        event.preventDefault();


                        selectTravelMode(
                            element.dataset.mode
                        );

                    }

                }
            );

        }
    );


    /*
     * Car is selected initially.
     */
    updateTravelModeUI(
        selectedTravelMode
    );


    // ================= DIRECTIONS MODAL =================

    if (
        modal &&
        openBtn &&
        closeBtn
    ) {

        if (routeHint) {

            routeHint.addEventListener(
                'click',
                () => {

                    modal.classList.add(
                        'active'
                    );


                    hideRouteHint();

                }
            );

        }


        openBtn.addEventListener(
            'click',
            () => {

                modal.classList.add(
                    'active'
                );

            }
        );


        closeBtn.addEventListener(
            'click',
            () => {

                modal.classList.remove(
                    'active'
                );

            }
        );


        modal.addEventListener(
            'click',
            event => {

                if (
                    event.target === modal
                ) {

                    modal.classList.remove(
                        'active'
                    );

                }

            }
        );

    }


    // ================= INITIAL GPS STATE =================

    /*
     * Tell the user that the browser is currently
     * attempting to obtain their location.
     */
    updateLocationStatus(
        'loading',
        'Getting your location…'
    );


    // ================= GPS =================

    /*
     * Check whether geolocation is supported before
     * attempting to use it.
     */
    if (
        !navigator.geolocation
    ) {

        updateLocationStatus(
            'error',
            'Location is not supported'
        );


        return;

    }


    navigator.geolocation.watchPosition(

        function (pos) {

            const userLat =
                pos.coords.latitude;

            const userLng =
                pos.coords.longitude;


            /*
             * Reject invalid GPS coordinates.
             */
            if (
                !Number.isFinite(userLat) ||
                !Number.isFinite(userLng)
            ) {

                updateLocationStatus(
                    'error',
                    'Invalid location received'
                );


                return;

            }


            userLocation = {

                lat:
                    userLat,

                lng:
                    userLng

            };


            /*
             * GPS is now available.
             */
            updateLocationStatus(
                'success',
                'Location found'
            );


            /*
             * Update all ETA cards.
             */
            updateTravelTimes(
                userLat,
                userLng
            );


            // ================= FIRST GPS UPDATE =================

            if (
                isFirstUpdate
            ) {

                userMarker =
                    L.marker(
                        [
                            userLat,
                            userLng
                        ],
                        {
                            icon:
                                userIcon
                        }
                    ).addTo(
                        navMap
                    );


                navMap.flyTo(
                    [
                        userLat,
                        userLng
                    ],
                    16,
                    {

                        animate:
                            true,

                        duration:
                            1.5

                    }
                );


                /*
                 * Create the initial car route.
                 */
                createRoute(
                    userLat,
                    userLng
                );


                isFirstUpdate =
                    false;


                return;

            }


            // ================= SUBSEQUENT GPS UPDATES =================

            if (userMarker) {

                userMarker.setLatLng([

                    userLat,

                    userLng

                ]);

            }


            /*
             * Update the displayed route's starting point.
             */
            updateRoute(
                userLat,
                userLng
            );

        },


        function (error) {

            console.error(
                'Geolocation error:',
                error.code
            );


            /*
             * Provide a specific message based on
             * the browser's geolocation error code.
             */
            let message =
                'Unable to get your location';


            if (
                error.code === 1
            ) {

                message =
                    'Location permission denied';

            }


            if (
                error.code === 2
            ) {

                message =
                    'Location unavailable';

            }


            if (
                error.code === 3
            ) {

                message =
                    'Location request timed out';

            }


            updateLocationStatus(
                'error',
                message
            );

        },


        {

            enableHighAccuracy:
                true,

            maximumAge:
                5000,

            timeout:
                10000

        }

    );

});